module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic x,
    output logic z
);

  // One-hot encoding:
  // bit 0: State A (2'b01)
  // bit 1: State B (2'b10)
  logic [1:0] state, next_state;

  always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= 2'b01; // State A
    end else begin
      state <= next_state;
    end
  end

  always_comb begin
    next_state = 2'b01;
    z = 1'b0;
    case (state)
      2'b01: begin // State A
        if (x) begin
          next_state = 2'b10;
          z = 1'b1;
        end else begin
          next_state = 2'b01;
          z = 1'b0;
        end
      end
      2'b10: begin // State B
        if (x) begin
          next_state = 2'b10;
          z = 1'b0;
        end else begin
          next_state = 2'b10;
          z = 1'b1;
        end
      end
      default: begin
        next_state = 2'b01;
        z = 1'b0;
      end
    endcase
  end

endmodule

